import clsx from "clsx";
import "./entry-tree.css";

interface EntryTreeProps {
  entries: Array<{id: string; label: string}>;
  selectedId?: string;
}

export const EntryTree = ({entries, selectedId}: EntryTreeProps) => (
  <ul
    className={clsx(
      "entriesEntryTree_list",
      selectedId && "entriesEntryTree_list--selected",
    )}
  >
    {entries.map((entry) => (
      <li className="entriesEntryTree_item" key={entry.id}>
        {entry.label}
      </li>
    ))}
  </ul>
);

.entriesEntryTree_list {
  /* Route-local list role; presentation intentionally remains unchanged. */
}

.entriesEntryTree_item {
  /* Route-local item role; presentation intentionally remains unchanged. */
}

.entriesEntryTree_list--selected {
  /* Route-local selected-state hook; presentation intentionally remains unchanged. */
}
